import{_ as a,c as n,o as e,ah as p}from"./chunks/framework.DE7iKuik.js";const h=JSON.parse('{"title":"扩展包源仓库","frontmatter":{"title":"扩展包源仓库","createTime":"2025/01/17 19:27:31","permalink":"/docs/composer/repositories.html","lastUpdated":"2026-01-22","tags":[],"link":"/docs/composer/教程/repositories","layout":"doc","sidebar":true,"aside":true,"prev":{"text":"json 完全解析","link":"/docs/composer/教程/schema"},"next":{"text":"配置信息","link":"/docs/composer/教程/config"}},"headers":[],"params":{"pkg":"composer/教程/repositories","sidebar":[{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]}],"versions":[]},"relativePath":"docs/composer/教程/repositories.md","filePath":"docs/[pkg].md"}'),l={name:"docs/composer/教程/repositories.md"};function o(i,s,t,c,r,u){return e(),n("div",null,[...s[0]||(s[0]=[p(`<h1 id="扩展包源仓库" tabindex="-1">扩展包源仓库 <a class="header-anchor" href="#扩展包源仓库" aria-label="Permalink to “扩展包源仓库”">​</a></h1><p>这一章节将说明包和仓库的概念，仓库是用来做什么的以及仓库的实现和工作方式。</p><h2 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to “概念”">​</a></h2><p>在我们了解已存在的不同类型的仓库之前，我们需要了解 Composer 构建的一些基本概念。</p><h3 id="包" tabindex="-1">包 <a class="header-anchor" href="#包" aria-label="Permalink to “包”">​</a></h3><p>Composer 是一个依赖管理器。 它能够将包安装在本地。一个包的本质是一个包括了一系列源文件的目录。一般的，一个包中的文件主要是一堆 PHP 代码文件，但理论上一个包里面可以包括任意类型的文件，其中一个文件就是包中用于描述包的名称和版本信息的文件。名称和版本是包的唯一标识。</p><p>事实上，Composer 的内部认为每一个版本都是独立的包，虽然对于使用 Composer 管理依赖时这并不重要，但对于你想要改变包中的一些东西时或做一些自定义选项时，这些内容则十分重要。</p><p>此外，除了名称和版本信息，还有一些其他有用的元数据。其中与安装包时最紧密相关的信息就是包来源的定义，这个是用于告知从何处去取得包的实际内容。来源分两种：dist 和 source。</p><p>Dist: dist 来源的包是一个打包后的分发版。通常是一个已发布的稳定版本。</p><p>Source: source 来源的包往往用于开发。通常是一个源代码仓库，例如 git。当你想要修改下载的包，你可以选择使用该来源。</p><p>包可以提供任意一种来源选项，或者二者皆有。最终选定哪一个取决于某一些因素，例如用户提供的指定选项、包的稳定性标识。</p><h3 id="仓库" tabindex="-1">仓库 <a class="header-anchor" href="#仓库" aria-label="Permalink to “仓库”">​</a></h3><p>仓库是包的来源。它提供了一个包和版本的列表。Composer 通过查阅你配置中定义的所有仓库源里去寻找你项目中所需要的包并将其引入。</p><p>Composer 将 Packagist 作为全局默认查找的仓库。当然你也可以通过在你的项目配置文件 —— <code>composer.json</code> 中添加额外的仓库源配置。</p><p>所有对于仓库源的配置信息仅在源包（ root package ）中有效，而该包中所依赖的包内对于仓库源的配置信息则不会再被 Composer 作为查找包的目标仓库的依据。你可以阅读 <a href="https://github.com/composer/composer/blob/master/doc/faqs/why-can&#39;t-composer-load-repositories-recursively.md" target="_blank" rel="noreferrer">FAQ entry</a> 了解更多具体原因。</p><h2 id="仓库类型" tabindex="-1">仓库类型 <a class="header-anchor" href="#仓库类型" aria-label="Permalink to “仓库类型”">​</a></h2><h3 id="composer" tabindex="-1">Composer <a class="header-anchor" href="#composer" aria-label="Permalink to “Composer”">​</a></h3><p>最主要、也是最常见的仓库类型就是 <code>composer</code> 仓库。这种类型的仓库使用 <code>packages.json</code> 文件来记录这个仓库中所有包的元数据。</p><p>这也是 Packagist 所使用的仓库类型。当 Composer 引入这种类型的仓库的包时，首先需要找到这个仓库提供的 <code>packages.json</code> 文件。我们以 Packagist 为例，该文件位于站点根路径的 <code>/packages.json</code>，所以仓库的地址就是 <code>repo.packagist.org</code>。再例如  <code>example.org/packages.json</code> 是某仓库的 <code>package.json</code> 文件的实际获取地址，则该仓库源地址就是 <code>example.org</code>。</p><h4 id="packages-字段" tabindex="-1">packages 字段 <a class="header-anchor" href="#packages-字段" aria-label="Permalink to “packages 字段”">​</a></h4><p>唯一必需的字段是<code>packages</code>。它的 JSON 结构如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;packages&quot;: {</span></span>
<span class="line"><span>        &quot;vendor/package-name&quot;: {</span></span>
<span class="line"><span>            &quot;dev-master&quot;: { @composer.json },</span></span>
<span class="line"><span>            &quot;1.0.x-dev&quot;: { @composer.json },</span></span>
<span class="line"><span>            &quot;0.0.1&quot;: { @composer.json },</span></span>
<span class="line"><span>            &quot;1.0.0&quot;: { @composer.json }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>@composer.json</code> 标记是包的指定版本里<code>composer.json</code>的内容，其内至少包含以下信息：</p><ul><li>包名<code>name</code></li><li>版本<code>version</code></li><li>来源<code>dist</code>或<code>source</code></li></ul><p>这是一个最简单的包定义：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;name&quot;: &quot;smarty/smarty&quot;,</span></span>
<span class="line"><span>    &quot;version&quot;: &quot;3.1.7&quot;,</span></span>
<span class="line"><span>    &quot;dist&quot;: {</span></span>
<span class="line"><span>        &quot;url&quot;: &quot;https://www.smarty.net/files/Smarty-3.1.7.zip&quot;,</span></span>
<span class="line"><span>        &quot;type&quot;: &quot;zip&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>它还可以包含任何在 <a href="https://learnku.com/docs/composer/2018/04-schema/2085" target="_blank" rel="noreferrer">composer.json 完全解析</a> 中描述的字段。</p><h4 id="notify-batch-字段" tabindex="-1">notify-batch 字段 <a class="header-anchor" href="#notify-batch-字段" aria-label="Permalink to “notify-batch 字段”">​</a></h4><p><code>notify-batch</code>字段允许指定 URL，它会在用户每安装一个包时被调用。这个 URL 可以是一个绝对路径（将使用与源仓库相同的域名），或者是一个完整的 URL 地址。</p><p>一个示例的值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;notify-batch&quot;: &quot;/downloads/&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>例如<code>example.org/packages.json</code>里包含<code>monolog/monolog</code>包，这将会发起一个<code>POST</code>请求到<code>example.org/downloads/</code>，并带有 JSON 格式的请求体（request body）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;downloads&quot;: [</span></span>
<span class="line"><span>        {&quot;name&quot;: &quot;monolog/monolog&quot;, &quot;version&quot;: &quot;1.2.1.0&quot;}</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>version</code>字段包含了标准化的版本号。</p><p>该字段是可选的。</p><h4 id="provider-includes-和-providers-url-字段" tabindex="-1">provider-includes 和 providers-url 字段 <a class="header-anchor" href="#provider-includes-和-providers-url-字段" aria-label="Permalink to “provider-includes 和 providers-url 字段”">​</a></h4><p><code>provider-includes</code>字段允许你设置一个列表，它包含了该仓库提供的一部分包名称。这种情况下哈希值应该是文件的 sha256。</p><p><code>providers-url</code>描述了怎样在服务器上查找 provider 文件，是一个相对源仓库根目录的绝对路径。必须包含<code>%package%</code> 和 <code>%hash%</code>这两个占位符。</p><p>示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;provider-includes&quot;: {</span></span>
<span class="line"><span>        &quot;providers-a.json&quot;: {</span></span>
<span class="line"><span>            &quot;sha256&quot;: &quot;f5b4bc0b354108ef08614e569c1ed01a2782e67641744864a74e788982886f4c&quot;</span></span>
<span class="line"><span>        },</span></span>
<span class="line"><span>        &quot;providers-b.json&quot;: {</span></span>
<span class="line"><span>            &quot;sha256&quot;: &quot;b38372163fac0573053536f5b8ef11b86f804ea8b016d239e706191203f6efac&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    &quot;providers-url&quot;: &quot;/p/%package%$%hash%.json&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这些文件包含包名称和哈希值，以此验证文件完整性，例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;providers&quot;: {</span></span>
<span class="line"><span>        &quot;acme/foo&quot;: {</span></span>
<span class="line"><span>            &quot;sha256&quot;: &quot;38968de1305c2e17f4de33aea164515bc787c42c7e2d6e25948539a14268bb82&quot;</span></span>
<span class="line"><span>        },</span></span>
<span class="line"><span>        &quot;acme/bar&quot;: {</span></span>
<span class="line"><span>            &quot;sha256&quot;: &quot;4dd24c930bd6e1103251306d6336ac813b563a220d9ca14f4743c032fb047233&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>上面的文件声明了 acme/foo 和 acme/bar 可以在该源仓库中找到，通过加载由<code>providers-url</code>引用的文件，替换<code>%package%</code>为发行商命名空间中的包名，替换<code>%hash%</code>为 sha256 字段值。这些文件均包含如上所述的 packages 字段定义。</p><p>这两个字段是可选的。你也许不需要它们来自定义存储库。</p><h4 id="流选项" tabindex="-1">流选项 <a class="header-anchor" href="#流选项" aria-label="Permalink to “流选项”">​</a></h4><p><code>packages.json</code>文件是使用 PHP 流加载的。你可以使用<code>options</code>参数设置额外的流选项。查看 <a href="https://secure.php.net/manual/zh/context.php" target="_blank" rel="noreferrer">上下文（Context）选项和参数 </a> 获取更多信息。</p><h3 id="vcs" tabindex="-1">VCS <a class="header-anchor" href="#vcs" aria-label="Permalink to “VCS”">​</a></h3><p>VCS 表示版本控制系统。这包括像 git、svn、fossil 和 hg 这样的版本控制系统。Composer 有一个仓库类型，可以从这些系统中安装软件包。</p><h4 id="从-vcs-仓库加载一个包" tabindex="-1">从 VCS 仓库加载一个包 <a class="header-anchor" href="#从-vcs-仓库加载一个包" aria-label="Permalink to “从 VCS 仓库加载一个包”">​</a></h4><p>这里有一些用例。最常见的情况是维护自己 Fork 的第三方库。如果你在项目中使用某个库并想对库做一些修改，你希望让你的项目使用这个修改版本。如果这个库是在 GitHub（这是最常见的）上，你可以直接 Fork 它然后推送更改到你的 Fork。然后更新项目的<code>composer.json</code>文件。你所需做的就是添加这个 Fork 并更新版本约束指向你自己的分支。在<code>composer.json</code>里，应该用<code>&quot;dev-&quot;</code>作为你自己分支的名称前缀。关于版本约束命名规范，请查看 <a href="https://learnku.com/docs/composer/2018/02-libraries/2083" target="_blank" rel="noreferrer">扩展包</a> 获取更多信息。</p><p>举个例子，假设你 Fork 了一份 monolog，并在<code>bugfix</code>分支修复了一个 bug：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;repositories&quot;: [</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;type&quot;: &quot;vcs&quot;,</span></span>
<span class="line"><span>            &quot;url&quot;: &quot;https://github.com/igorw/monolog&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    ],</span></span>
<span class="line"><span>    &quot;require&quot;: {</span></span>
<span class="line"><span>        &quot;monolog/monolog&quot;: &quot;dev-bugfix&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>当运行<code>php composer.phar update</code>时，你应该会获得自己的<code>monolog/monolog</code>修改版本，而不是 packagist 上的。</p><p>注意，你不能重命名软件包，除非你打算脱离原来的包，长期使用 Fork 的。由于自定义仓库优先于 packagist，这样 Composer 就能正确地获取你的包了。如果你一定要重命名包，你应该在默认分支（通常是 master）进行操作，而不是某个特性分支，因为包的名称取自默认分支。</p><p>也请注意，如果你在自己 Fork 的仓库修改了<code>composer.json</code> 里的<code>name</code>属性，覆盖操作将无法工作，因为这需要匹配原来的包让操作生效。</p><p>如果其他的包依赖于你的 Fork，可能你需要设置行内别名以匹配对应的版本约束。更多信息请查看 <a href="https://learnku.com/docs/composer/2018/aliases/2089" target="_blank" rel="noreferrer">分支别名</a> 。</p><h4 id="使用私有源仓库" tabindex="-1">使用私有源仓库 <a class="header-anchor" href="#使用私有源仓库" aria-label="Permalink to “使用私有源仓库”">​</a></h4><p>完全相同的解决方案允许您在 GitHub 和 BitBucket 上使用您的私有存储库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;require&quot;: {</span></span>
<span class="line"><span>        &quot;vendor/my-private-repo&quot;: &quot;dev-master&quot;</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    &quot;repositories&quot;: [</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;type&quot;: &quot;vcs&quot;,</span></span>
<span class="line"><span>            &quot;url&quot;:  &quot;git@bitbucket.org:vendor/my-private-repo.git&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>唯一的要求是为 git 客户端安装 SSH 密钥。</p><h4 id="git-备选方案" tabindex="-1">Git 备选方案 <a class="header-anchor" href="#git-备选方案" aria-label="Permalink to “Git 备选方案”">​</a></h4><p>Git 不是 VCS 存储库支持的唯一版本控制系统。支持以下内容：</p><ul><li>Git: <a href="https://git-scm.com/" target="_blank" rel="noreferrer">git-scm.com</a></li><li>Subversion: <a href="https://subversion.apache.org/" target="_blank" rel="noreferrer">subversion.apache.org</a></li><li>Mercurial: <a href="https://www.mercurial-scm.org/" target="_blank" rel="noreferrer">mercurial-scm.org</a></li><li>Fossil: <a href="https://www.fossil-scm.org/" target="_blank" rel="noreferrer">fossil-scm.org</a></li></ul><p>要从这些系统获取软件包，您需要安装它们各自的客户端，这可能很不方便。因此，GitHub 和 BitBucket 支持使用这些站点提供的API，无需安装版本控制系统即可获取软件包。 VCS 存储库为它们提供了 <code>dist</code>，它们将包作为拉链获取。</p><ul><li>GitHub: <a href="https://github.com/" target="_blank" rel="noreferrer">github.com</a> (Git)</li><li>BitBucket: <a href="https://bitbucket.org/" target="_blank" rel="noreferrer">bitbucket.org</a> (Git and Mercurial)</li></ul><p>Composer 将根据 URL 自动检测要使用的 VCS 驱动， 但是如果因为一些原因需要指定一个，可以使用 <code>git-bitbucket</code>，<code>hg-bitbucket</code>，<code>github</code>，<code>gitlab</code>，<code>perforce</code>，<code>fossil</code>，<code>git</code>，<code>svn</code> 或 <code>hg</code> 作为存储库类型来替代 <code>vcs</code>。</p><p>如果在 github 上将 <code>no-api</code> 设置为<code>true</code>，它将像使用任何其他 git 存储库而不是使用 GitHub API 一样克隆存储库。但与直接使用 <code>git</code> 驱动程序不同，Composer仍会尝试使用 github 的zip文件。</p><p>请注意：</p><ul><li>要让 Composer 选择使用哪个驱动程序，需要将存储库类型定义为 “vcs”</li><li>如果您已经使用了私有存储库，这意味着 Composer 应该已将其克隆到缓存中。如果你想用驱动程序安装相同的软件包，记得启动命令 <code>composer clearcache</code>，然后使用命令 <code>composer update</code> 来更新composer cache 并从 dist 安装软件包。</li></ul><h4 id="bitbucket-驱动配置" tabindex="-1">BitBucket 驱动配置 <a class="header-anchor" href="#bitbucket-驱动配置" aria-label="Permalink to “BitBucket 驱动配置”">​</a></h4><p>BitBucket 驱动使用 OAuth 来通过 BitBucket 的 REST API 获取你的私人仓库所以你需要创建一个 OAuth 用户来使用此驱动，详见 <a href="https://confluence.atlassian.com/bitbucket/oauth-on-bitbucket-cloud-238027431.html" target="_blank" rel="noreferrer">Atlassian 的文档</a>。你需要填写回调地址来满足 BitBucket 的需求，但该地址不需要在任意情况下被访问并且不会被 Composer 使用。</p><p>在 BitBucket 的控制面板创建了一个 OAuth 用户之后，你需要在 auth.json 文件中像这样填写凭据 （详见 <a href="https://getcomposer.org/doc/06-config.md#bitbucket-oauth" target="_blank" rel="noreferrer">这里</a>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;bitbucket-oauth&quot;: {</span></span>
<span class="line"><span>        &quot;bitbucket.org&quot;: {</span></span>
<span class="line"><span>            &quot;consumer-key&quot;: &quot;myKey&quot;,</span></span>
<span class="line"><span>            &quot;consumer-secret&quot;: &quot;mySecret&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>注意仓库地址要是 HTTPS 而不是 Git。</p><p>如果你不想在文件系统中存储 OAuth 凭据，你可以设置 <code>bitbucket-oauth</code> 到  <a href="https://getcomposer.org/doc/03-cli.md#composer-auth" target="_blank" rel="noreferrer">COMPOSER_AUTH</a> 环境变量中来替代。</p><h4 id="svn-设置" tabindex="-1">SVN 设置 <a class="header-anchor" href="#svn-设置" aria-label="Permalink to “SVN 设置”">​</a></h4><p>由于 SVN 没有原生分支以及标签的概念，Composer 默认代码在 <code>$url/trunk</code>, <code>$url/branches</code> 和 <code>$url/tags</code> 里。如果你的仓库结构不同，你可以更改那些值。例如你使用首字母大写的名字，你可以像这样配置你的仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;repositories&quot;: [</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;type&quot;: &quot;vcs&quot;,</span></span>
<span class="line"><span>            &quot;url&quot;: &quot;http://svn.example.org/projectA/&quot;,</span></span>
<span class="line"><span>            &quot;trunk-path&quot;: &quot;Trunk&quot;,</span></span>
<span class="line"><span>            &quot;branches-path&quot;: &quot;Branches&quot;,</span></span>
<span class="line"><span>            &quot;tags-path&quot;: &quot;Tags&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如果你没有分支或标签目录，你可以把 <code>branches-path</code> 或 <code>tags-path</code> 设置为 <code>false</code> 来完全禁用他们。</p><p>如果包在一个二级目录， 例如 <code>/trunk/foo/bar/composer.json</code> 和 <code>/tags/1.0/foo/bar/composer.json</code>，这时你可以设置 <code>&quot;package-path&quot;</code> 选项为二级目录路径来让 Composer 获取它，在这个例子中是 <code>&quot;package-path&quot;: &quot;foo/bar/&quot;</code>。</p><p>如果你用的是私人 SVN 仓库，你可以将凭据保存在设置文件中的 http-basic 项中（详见 <a href="https://github.com/composer/composer/blob/master/doc/04-schema.md" target="_blank" rel="noreferrer">Schema</a>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;http-basic&quot;: {</span></span>
<span class="line"><span>        &quot;svn.example.org&quot;: {</span></span>
<span class="line"><span>            &quot;username&quot;: &quot;username&quot;,</span></span>
<span class="line"><span>            &quot;password&quot;: &quot;password&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如果你的 SVN 客户端设置为存储用户凭据，那该用户的凭据会默认存储，而已存在的凭据会被覆盖。通过在仓库中设置 <code>&quot;svn-cache-credentials&quot;</code> 来禁止该行为：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;repositories&quot;: [</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;type&quot;: &quot;vcs&quot;,</span></span>
<span class="line"><span>            &quot;url&quot;: &quot;http://svn.example.org/projectA/&quot;,</span></span>
<span class="line"><span>            &quot;svn-cache-credentials&quot;: false</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="pear" tabindex="-1">PEAR <a class="header-anchor" href="#pear" aria-label="Permalink to “PEAR”">​</a></h3><p>使用 <code>pear</code> 仓库可以从任何 PEAR 频道安装扩展包。Composer 会以 <code>pear-{channelName}/</code> 前缀来命名所有的扩展包来避免冲突。所有扩展包也会用 <code>pear-{channelAlias}/</code> 前缀来做别名。</p><p>比如使用 <code>pear2.php.net</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;repositories&quot;: [</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;type&quot;: &quot;pear&quot;,</span></span>
<span class="line"><span>            &quot;url&quot;: &quot;https://pear2.php.net&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    ],</span></span>
<span class="line"><span>    &quot;require&quot;: {</span></span>
<span class="line"><span>        &quot;pear-pear2.php.net/PEAR2_Text_Markdown&quot;: &quot;*&quot;,</span></span>
<span class="line"><span>        &quot;pear-pear2/PEAR2_HTTP_Request&quot;: &quot;*&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在这个例子中频道的简短命名是 <code>pear2</code>，所以 <code>PEAR2_HTTP_Request</code> 包命名就变成了 <code>pear-pear2/PEAR2_HTTP_Request</code>。</p><blockquote><p>注意： <code>pear</code> 仓库需要为每一个包做一些网络请求，所以这可能会使安装过程变慢。</p></blockquote><h4 id="自定义-vendor-别名" tabindex="-1">自定义 vendor 别名 <a class="header-anchor" href="#自定义-vendor-别名" aria-label="Permalink to “自定义 vendor 别名”">​</a></h4><p>也可以用自定义 vendor 名称来为 PEAR 频道做别名。</p><p>例如：</p><p>设想下你有一个私人 PEAR 仓库，并且想使用 Composer 来从 VCS 中来包含一些依赖。你的 PEAR 仓库包含以下扩展包：</p><ul><li><code>BasePackage</code></li><li><code>IntermediatePackage</code>，依赖 <code>BasePackage</code></li><li><code>TopLevelPackage1</code> 和 <code>TopLevelPackage2</code> 都依赖 <code>IntermediatePackage</code></li></ul><p>如果没有 vendor 别名，Composer 会使用 PEAR 频道名作为包名的一部分：</p><ul><li><code>pear-pear.foobar.repo/BasePackage</code></li><li><code>pear-pear.foobar.repo/IntermediatePackage</code></li><li><code>pear-pear.foobar.repo/TopLevelPackage1</code></li><li><code>pear-pear.foobar.repo/TopLevelPackage2</code></li></ul><p>设想之后的某个时间你想要把 PEAR 包迁移到一个 Composer 仓库里，并且采用了 <code>foobar</code> 的 vendor 名称。使用你的 PEAR 包的项目不会看到更新后的包，因为它们的 vendor 名字变了 (<code>foobar/IntermediatePackage</code> 对比 <code>pear-pear.foobar.repo/IntermediatePackage</code>).</p><p>通过一开始就为 PEAR 仓库指定 <code>vendor-alias</code>，你可以避免这种情况并且你的包名都不会过期。</p><p>举例来说，下面的例子会从 PEAR 仓库获取 <code>BasePackage</code>、<code>TopLevelPackage1</code> 和  <code>TopLevelPackage2</code> 包，以及从 Github 仓库获取 <code>IntermediatePackage</code> 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;repositories&quot;: [</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;type&quot;: &quot;git&quot;,</span></span>
<span class="line"><span>            &quot;url&quot;: &quot;https://github.com/foobar/intermediate.git&quot;</span></span>
<span class="line"><span>        },</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;type&quot;: &quot;pear&quot;,</span></span>
<span class="line"><span>            &quot;url&quot;: &quot;http://pear.foobar.repo&quot;,</span></span>
<span class="line"><span>            &quot;vendor-alias&quot;: &quot;foobar&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    ],</span></span>
<span class="line"><span>    &quot;require&quot;: {</span></span>
<span class="line"><span>        &quot;foobar/TopLevelPackage1&quot;: &quot;*&quot;,</span></span>
<span class="line"><span>        &quot;foobar/TopLevelPackage2&quot;: &quot;*&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="package" tabindex="-1">Package <a class="header-anchor" href="#package" aria-label="Permalink to “Package”">​</a></h3><p>如果你有一个通过以上任意方法都用不了 Composer 的项目，你仍可以通过使用 <code>package</code> 仓库来自己定义包。</p><p>最基础的，定义与 <code>composer</code> 仓库中 <code>packages.json</code> 已包含的相同信息，但这只适用于单独的包。最少必须项是 <code>name</code>, <code>version</code> 以及 <code>dist</code> 或 <code>source</code>。</p><p>这有一个 smarty 模板引擎的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;repositories&quot;: [</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;type&quot;: &quot;package&quot;,</span></span>
<span class="line"><span>            &quot;package&quot;: {</span></span>
<span class="line"><span>                &quot;name&quot;: &quot;smarty/smarty&quot;,</span></span>
<span class="line"><span>                &quot;version&quot;: &quot;3.1.7&quot;,</span></span>
<span class="line"><span>                &quot;dist&quot;: {</span></span>
<span class="line"><span>                    &quot;url&quot;: &quot;https://www.smarty.net/files/Smarty-3.1.7.zip&quot;,</span></span>
<span class="line"><span>                    &quot;type&quot;: &quot;zip&quot;</span></span>
<span class="line"><span>                },</span></span>
<span class="line"><span>                &quot;source&quot;: {</span></span>
<span class="line"><span>                    &quot;url&quot;: &quot;http://smarty-php.googlecode.com/svn/&quot;,</span></span>
<span class="line"><span>                    &quot;type&quot;: &quot;svn&quot;,</span></span>
<span class="line"><span>                    &quot;reference&quot;: &quot;tags/Smarty_3_1_7/distribution/&quot;</span></span>
<span class="line"><span>                },</span></span>
<span class="line"><span>                &quot;autoload&quot;: {</span></span>
<span class="line"><span>                    &quot;classmap&quot;: [&quot;libs/&quot;]</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    ],</span></span>
<span class="line"><span>    &quot;require&quot;: {</span></span>
<span class="line"><span>        &quot;smarty/smarty&quot;: &quot;3.1.*&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如果你并不真正需要 <code>source</code> 部分，可以把它留空。</p><blockquote><p>注意：仓库类型有一些限制并且应该尽可能地避免：</p><ul><li>Composer 不会升级依赖包除非你修改了 <code>version</code> 字段。</li><li>Composer 不会更新提交记录，所以如果你使用 <code>master</code> 作为引用，你必须把包删除来强制更新，并且处理一个不稳定的 lock 文件。</li></ul></blockquote><p><code>package</code> 仓库里的 <code>&quot;package&quot;</code> 项可以设置为一个数组来定义包的不同版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;repositories&quot;: [</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;type&quot;: &quot;package&quot;,</span></span>
<span class="line"><span>            &quot;package&quot;: [</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    &quot;name&quot;: &quot;foo/bar&quot;,</span></span>
<span class="line"><span>                    &quot;version&quot;: &quot;1.0.0&quot;,</span></span>
<span class="line"><span>                    ...</span></span>
<span class="line"><span>                },</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    &quot;name&quot;: &quot;foo/bar&quot;,</span></span>
<span class="line"><span>                    &quot;version&quot;: &quot;2.0.0&quot;,</span></span>
<span class="line"><span>                    ...</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>            ]</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="自建-composer-仓库" tabindex="-1">自建 Composer 仓库 <a class="header-anchor" href="#自建-composer-仓库" aria-label="Permalink to “自建 Composer 仓库”">​</a></h2><p>大多数情况下你可能想把包放在 Packagist 上，但也有会使用自建仓库的情况。</p><ul><li><p>公司私有包：如果你所在的公司使用内部的 Composer 包，你可能会把那些包作为私有。</p></li><li><p>独立生态系统：如果你有一个有自己生态系统的项目，并且其中的包不会被大多数 PHP 社区所使用，你可能会把他们存储在别处而不是 Packagist。WordPress 插件就是一个例子。</p></li></ul><p>要自建包仓库，原生 <code>composer</code> 仓库类型是必须的，这会提供最好的性能。</p><p>有一些工具可以帮助你创建 <code>composer</code> 仓库。</p><h3 id="私有的-packagist" tabindex="-1">私有的 Packagist <a class="header-anchor" href="#私有的-packagist" aria-label="Permalink to “私有的 Packagist”">​</a></h3><p><a href="https://packagist.com/" target="_blank" rel="noreferrer">Private Packagist</a> 是一个可以提供私人扩展包主机，以及 GitHub、Packagist.org 和其他包仓库镜像的应用。</p><p>详见 <a href="https://packagist.com/" target="_blank" rel="noreferrer">Packagist.com</a>。</p><h3 id="satis" tabindex="-1">Satis <a class="header-anchor" href="#satis" aria-label="Permalink to “Satis”">​</a></h3><p>Satis 是一个静态 <code>composer</code> 仓库生成器，它很像是一个轻量和静态文件版本的 Packagist。</p><p>给他一个包含仓库的 <code>composer.json</code> 文件，典型的 VCS 和包仓库定义。它会获取所有 <code>required</code> 的包并且把它们 dump 到一个 <code>packages.json</code> 文件中，它就是你的 <code>composer</code> 仓库。</p><p>详见 <a href="https://github.com/composer/satis" target="_blank" rel="noreferrer">Satis GitHub 仓库</a> 和 <a href="https://github.com/composer/composer/blob/master/doc/articles/handling-private-packages-with-satis.md" target="_blank" rel="noreferrer">Satis 文章</a>。</p><h3 id="工件" tabindex="-1">工件 <a class="header-anchor" href="#工件" aria-label="Permalink to “工件”">​</a></h3><p>有些情况，无法使用之前提到的任意一种类型的在线仓库，甚至是 VCS。 典型的例子是通过构建工件来跨组织共享资源，当然大多数情况下是私有资源。为了便于维护，可以使用 <code>工件（artifact）</code> 仓库类型来指定包含那些 ZIP 压缩包的文件夹：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;repositories&quot;: [</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;type&quot;: &quot;artifact&quot;,</span></span>
<span class="line"><span>            &quot;url&quot;: &quot;path/to/directory/with/zips/&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    ],</span></span>
<span class="line"><span>    &quot;require&quot;: {</span></span>
<span class="line"><span>        &quot;private-vendor-one/core&quot;: &quot;15.6.2&quot;,</span></span>
<span class="line"><span>        &quot;private-vendor-two/connectivity&quot;: &quot;*&quot;,</span></span>
<span class="line"><span>        &quot;acme-corp/parser&quot;: &quot;10.3.5&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>每个 ZIP 压缩包内的根目录都有一个 <code>composer.json</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>unzip -l acme-corp-parser-10.3.5.zip</span></span>
<span class="line"><span></span></span>
<span class="line"><span>composer.json</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>如果一个包有两个不同版本的压缩文件，那它们可以被同时导入。当新版本的压缩文件被添加到了工件中，并且你执行了 <code>update</code>，则这个新版本会被导入并且 Composer 会升级此扩展包至最新版本。</p><h3 id="文件夹路径" tabindex="-1">文件夹路径 <a class="header-anchor" href="#文件夹路径" aria-label="Permalink to “文件夹路径”">​</a></h3><p>除了工件类型仓库，你还可以使用 <code>文件夹路径（path）</code> 类型仓库，它允许你依赖一个本地目录，可以是相对或绝对路径，在处理比较大的仓库时会显得格外有用。</p><p>举例来说，如果你的仓库中目录结构是这样的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- apps</span></span>
<span class="line"><span>\\_ my-app</span></span>
<span class="line"><span>  \\_ composer.json</span></span>
<span class="line"><span>- packages</span></span>
<span class="line"><span>\\_ my-package</span></span>
<span class="line"><span>  \\_ composer.json</span></span></code></pre></div><p>接着，在你的 <code>apps/my-app/composer.json</code> 文件中要添加 <code>my/package</code> 包作为一个依赖，你可以使用如下配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;repositories&quot;: [</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;type&quot;: &quot;path&quot;,</span></span>
<span class="line"><span>            &quot;url&quot;: &quot;../../packages/my-package&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    ],</span></span>
<span class="line"><span>    &quot;require&quot;: {</span></span>
<span class="line"><span>        &quot;my/package&quot;: &quot;*&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如果扩展包是一个本地 VCS 仓库，那它的版本会根据当前已检出的分支或标签推断出来。否则，你应该在 <code>composer.json</code> 文件中显式定义出它的版本。如果版本不能被读取或获取，则默认会是 <code>dev-master</code>。</p><p>本地扩展包会尽可能的被做为符号链接来引用，此时控制台输出会是 <code>来自 ../../packages/my-package 的符号链接 </code>。如果符号链接 <em>不可用</em>，则包会被完整地拷贝（镜像）过来以供引用。这时，控制台输出会是 <code>来自 ../../packages/my-package 的镜像</code>。</p><p>如果不想使用这种默认的 <code>不可用则替代</code> 策略，你可以设置 <code>&quot;symlink&quot;: true</code> 来强制使用符号链接或 <code>&quot;symlink&quot;: false</code> 来强制使用镜像。在需要部署或是要从大型仓库生成扩展包会时强制使用镜像会很有用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;repositories&quot;: [</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;type&quot;: &quot;path&quot;,</span></span>
<span class="line"><span>            &quot;url&quot;: &quot;../../packages/my-package&quot;,</span></span>
<span class="line"><span>            &quot;options&quot;: {</span></span>
<span class="line"><span>                &quot;symlink&quot;: false</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>~</code> 会被展开成用户的 HOME 文件夹，并且可以根据不同的环境被解析成 Windows 和 Linux/Mac 使用的形式。例如 <code>~/git/mypackage</code> 会自动从 Linux 的 <code>/home/&lt;username&gt;/git/mypackage</code> 目录加载 mypackage，在 Mac 上是 <code>$HOME/git/mypackage</code> 目录，而在 Windows 则是 <code>%USERPROFILE%/git/mypackage</code> 目录。</p><blockquote><p>注意：仓库路径也可以包含通配符，例如 <code>*</code> 和 <code>?</code>。详见 <a href="http://php.net/glob" target="_blank" rel="noreferrer">PHP glob function</a>。</p></blockquote><h2 id="禁用-packagist-org" tabindex="-1">禁用 Packagist.org <a class="header-anchor" href="#禁用-packagist-org" aria-label="Permalink to “禁用 Packagist.org”">​</a></h2><p>你可以将以下内容添加到 <code>composer.json</code>，以禁用默认的 Packagist.org 仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;repositories&quot;: [</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;packagist.org&quot;: false</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>你也可以使用全局配置标识来禁用 Packagist.org ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>composer config -g repo.packagist false</span></span></code></pre></div>`,145)])])}const g=a(l,[["render",o]]);export{h as __pageData,g as default};
